// Cálculos do mapa do checkout. Cada fn é autocontida: o leitor vê exatamente a regra aplicada.

dash.calc('transacoes', {
  title: 'Transações × contrato',
  description: 'Cada linha da Orbe com a faixa do contrato, a taxa contratada vigente na data e a diferença em reais (taxa truncada em centavos, como a Orbe faz).',
  inputs: ['orbe_transacoes', 'taxas_contratadas'],
  fn: (orbe_transacoes, taxas_contratadas) => {
    const faixaDe = (r) => {
      if (r.tipo === 'ANTECIPACAO' || r.tipo === 'REVERSAO ANTECIPACAO') return 'antecipacao';
      if (r.modalidade === 'DEBITO') return 'debito';
      if (r.modalidade === 'PIX') return 'pix';
      if (r.modalidade === 'CREDITO A VISTA') return 'credito_avista';
      return Number(r.parcelas) <= 6 ? 'credito_2_6' : 'credito_7_12';
    };
    const vigente = (linhas, dia) => linhas.filter((t) => (!t.vig_inicio || t.vig_inicio <= dia) && (!t.vig_fim || dia <= t.vig_fim));
    // taxa em centavos, truncada: inteiros para não errar por ponto flutuante
    const taxaCent = (bruto, pct) => {
      const p = Math.round(bruto * 100) * Math.round(pct * 100);
      return Math.trunc(p / 10000);
    };
    const arred = (bruto, pct) => Math.round(Math.abs(bruto) * pct) / 100 * Math.sign(bruto);
    const porEc = {};
    for (const t of taxas_contratadas) if (t.ec) (porEc[t.ec] = porEc[t.ec] || []).push(t);
    return orbe_transacoes.map((r) => {
      const bruto = Number(r.valor_bruto), aplicada = Number(r.taxa_aplicada_pct), vtaxa = Number(r.valor_taxa);
      const faixa = faixaDe(r);
      const contratos = porEc[r.ec] || [];
      const vMov = vigente(contratos, r.data_movimento)[0];
      const vVenda = r.data_venda_original ? vigente(contratos, r.data_venda_original)[0] : vMov;
      const contratada = vMov && vMov[faixa] !== '' ? Number(vMov[faixa]) : null;
      const contratadaVenda = vVenda && vVenda[faixa] !== '' ? Number(vVenda[faixa]) : null;
      const status = !contratos.length ? 'sem_contrato' : contratada === null ? 'sem_taxa' : Math.abs(contratada - aplicada) < 1e-9 ? 'ok' : 'divergente';
      const esperadaCent = contratada === null ? null : taxaCent(bruto, contratada);
      return {
        id_transacao: r.id_transacao, linha_arquivo: r.linha_arquivo, data: r.data_movimento, ec: r.ec,
        nome_orbe: r.nome_orbe, tipo: r.tipo, faixa, parcelas: r.parcelas, valor_bruto: bruto,
        taxa_aplicada_pct: aplicada, valor_taxa: vtaxa,
        taxa_contratada_pct: contratada, taxa_contratada_venda_pct: contratadaVenda,
        linha_planilha: vMov ? vMov.linha_planilha : '', lojista: vMov ? vMov.lojista : '',
        status,
        diferenca_brl: esperadaCent === null ? null : Math.round(vtaxa * 100 - esperadaCent) / 100,
        trunca_ok: taxaCent(bruto, aplicada) === Math.round(vtaxa * 100),
        arredonda_ok: Math.abs(arred(bruto, aplicada) - vtaxa) < 0.005,
        id_referencia: r.id_referencia, data_venda_original: r.data_venda_original,
      };
    });
  },
});

dash.calc('ecs', {
  title: 'ECs da Orbe × planilha',
  description: 'Um estabelecimento (EC) por linha: os nomes com que aparece na Orbe, a linha da planilha que tem o mesmo EC e, quando não há, quais lojistas sem EC têm taxas iguais às aplicadas.',
  inputs: ['transacoes', 'taxas_contratadas'],
  fn: (transacoes, taxas_contratadas) => {
    const faixas = ['debito', 'credito_avista', 'credito_2_6', 'credito_7_12', 'pix'];
    const semEc = taxas_contratadas.filter((t) => !t.ec && t.credito_avista !== '');
    const g = {};
    for (const r of transacoes) {
      const e = (g[r.ec] = g[r.ec] || { ec: r.ec, nomes: {}, linhas: 0, bruto_vendas: 0, divergentes: 0, diferenca_brl: 0, lojista: r.lojista, linha_planilha: r.linha_planilha, status: r.status === 'sem_contrato' ? 'sem_contrato' : 'casado', aplicadas: {} });
      e.nomes[r.nome_orbe] = (e.nomes[r.nome_orbe] || 0) + 1;
      e.linhas += 1;
      if (r.tipo === 'VENDA') e.bruto_vendas += r.valor_bruto;
      if (r.status === 'divergente') { e.divergentes += 1; e.diferenca_brl += r.diferenca_brl; }
      if (r.tipo === 'VENDA' && faixas.includes(r.faixa)) (e.aplicadas[r.faixa] = e.aplicadas[r.faixa] || new Set()).add(r.taxa_aplicada_pct);
    }
    return Object.values(g).map((e) => {
      const candidatos = e.status === 'sem_contrato'
        ? semEc.filter((t) => Object.entries(e.aplicadas).every(([f, s]) => s.size === 1 && Math.abs(Number(t[f]) - [...s][0]) < 1e-9)).map((t) => t.lojista)
        : [];
      const lojistas = [...new Set(taxas_contratadas.filter((t) => t.ec === e.ec).map((t) => t.lojista))];
      return {
        ec: e.ec, nomes_orbe: Object.keys(e.nomes).sort().join(' | '), n_nomes: Object.keys(e.nomes).length,
        linhas: e.linhas, bruto_vendas: Math.round(e.bruto_vendas * 100) / 100,
        status: e.status, lojista_planilha: lojistas.join(' | '),
        linhas_planilha: taxas_contratadas.filter((t) => t.ec === e.ec).map((t) => t.linha_planilha).join(', '),
        candidatos_por_taxa: candidatos.join(' | '), n_candidatos: candidatos.length,
        divergentes: e.divergentes, diferenca_brl: Math.round(e.diferenca_brl * 100) / 100,
      };
    }).sort((a, b) => (a.lojista_planilha || 'zz' + a.nomes_orbe).localeCompare(b.lojista_planilha || 'zz' + b.nomes_orbe));
  },
});

dash.calc('matriz', {
  title: 'Taxa aplicada × contratada por faixa',
  description: 'Para cada EC e faixa do contrato: quantas linhas, quais taxas a Orbe aplicou, a contratada e quanto diverge em reais.',
  inputs: ['transacoes'],
  fn: (transacoes) => {
    const g = {};
    for (const r of transacoes) {
      const k = r.ec + '|' + r.faixa;
      const c = (g[k] = g[k] || { chave: k, ec: r.ec, faixa: r.faixa, linhas: 0, aplicadas: new Set(), contratadas: new Set(), divergentes: 0, diferenca_brl: 0, sem_contrato: r.status === 'sem_contrato' });
      c.linhas += 1;
      c.aplicadas.add(r.taxa_aplicada_pct);
      if (r.taxa_contratada_pct !== null) c.contratadas.add(r.taxa_contratada_pct);
      if (r.status === 'divergente') { c.divergentes += 1; c.diferenca_brl += r.diferenca_brl; }
    }
    return Object.values(g).map((c) => ({
      chave: c.chave, ec: c.ec, faixa: c.faixa, linhas: c.linhas,
