    }));
  },
});

dash.calc('vinculos', {
  title: 'Estornos e reversões → origem',
  description: 'Cada estorno e reversão com a linha que ele cita em id_referencia: se ela está no arquivo de setembro e se a taxa é a mesma da venda original.',
  inputs: ['transacoes'],
  fn: (transacoes) => {
    const porId = {};
    for (const r of transacoes) porId[r.id_transacao] = r;
    return transacoes.filter((r) => r.id_referencia).map((r) => {
      const o = porId[r.id_referencia];
      return {
        id_transacao: r.id_transacao, tipo: r.tipo, ec: r.ec, nome_orbe: r.nome_orbe, faixa: r.faixa,
        data: r.data, id_referencia: r.id_referencia, data_venda_original: r.data_venda_original,
        origem_no_arquivo: !!o, valor_bruto: r.valor_bruto, valor_origem: o ? o.valor_bruto : null,
        taxa_aplicada_pct: r.taxa_aplicada_pct, taxa_origem_pct: o ? o.taxa_aplicada_pct : null,
        mesma_taxa: o ? Math.abs(o.taxa_aplicada_pct - r.taxa_aplicada_pct) < 1e-9 : null,
        valor_total: o ? Math.abs(o.valor_bruto + r.valor_bruto) < 0.005 : null,
        taxa_contratada_pct: r.taxa_contratada_pct, taxa_contratada_venda_pct: r.taxa_contratada_venda_pct,
