dash.calc('kpis', {
  title: 'Números do mês',
  description: 'Totais de setembro usados no topo da página.',
  inputs: ['transacoes', 'ecs'],
  fn: (transacoes, ecs) => {
    const soma = (a, f) => Math.round(a.reduce((s, r) => s + f(r), 0) * 100) / 100;
    const div = transacoes.filter((r) => r.status === 'divergente');
    const sem = transacoes.filter((r) => r.status === 'sem_contrato');
    return [{
      linhas: transacoes.length,
      vendas: transacoes.filter((r) => r.tipo === 'VENDA').length,
      estornos: transacoes.filter((r) => r.tipo === 'ESTORNO').length,
      antecipacoes: transacoes.filter((r) => r.tipo === 'ANTECIPACAO').length,
      reversoes: transacoes.filter((r) => r.tipo === 'REVERSAO ANTECIPACAO').length,
      ecs: ecs.length,
      ecs_casados: ecs.filter((e) => e.status === 'casado').length,
      ecs_sem_contrato: ecs.filter((e) => e.status === 'sem_contrato').length,
      linhas_sem_contrato: sem.length,
      bruto_sem_contrato: soma(sem, (r) => r.valor_bruto),
      linhas_divergentes: div.length,
      diferenca_brl: soma(div, (r) => r.diferenca_brl),
      trunca_ok: transacoes.filter((r) => r.trunca_ok).length,
