});

dash.calc('hipoteses', {
  title: 'Hipóteses do checkout',
  description: 'Cada hipótese da exploração com o que os dados de setembro dizem sobre ela.',
  inputs: ['transacoes', 'ecs', 'vinculos', 'taxas_contratadas'],
  fn: (transacoes, ecs, vinculos, taxas_contratadas) => {
    const n = (x) => x.toLocaleString('pt-BR');
    const brl = (x) => x.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
    const soma = (a) => Math.round(a.reduce((s, r) => s + r.diferenca_brl, 0) * 100) / 100;
    const multi = ecs.filter((e) => e.n_nomes > 1);
    const nomeEmVariosEc = (() => { const m = {}; for (const r of transacoes) (m[r.nome_orbe] = m[r.nome_orbe] || new Set()).add(r.ec); return Object.values(m).filter((s) => s.size > 1).length; })();
    const trunca = transacoes.filter((r) => r.trunca_ok).length;
    const arred = transacoes.filter((r) => r.arredonda_ok).length;
    const sem = ecs.filter((e) => e.status === 'sem_contrato');
    const semLinhas = sem.reduce((s, e) => s + e.linhas, 0);
    const rota = transacoes.filter((r) => r.ec === '1074504011' && r.status === 'divergente');
    const rotaDesde = rota.map((r) => r.data).sort()[0] || '';
    const bridge = transacoes.filter((r) => r.ec === '1075624862' && r.status === 'divergente');
    const est = vinculos.filter((v) => v.tipo === 'ESTORNO');
    const rev = vinculos.filter((v) => v.tipo !== 'ESTORNO');
    const estMesma = est.filter((v) => v.mesma_taxa).length;
    const estVig = est.filter((v) => v.taxa_contratada_pct !== v.taxa_contratada_venda_pct).length;
    const ant = transacoes.filter((r) => r.faixa === 'antecipacao');
    const antTaxas = [...new Set(ant.map((r) => r.taxa_aplicada_pct))];
    const outras = transacoes.filter((r) => r.status === 'divergente' && r.ec !== '1074504011' && r.ec !== '1075624862');
    const cnpj13 = taxas_contratadas.filter((t) => t.cnpj_digitos && t.cnpj_digitos.length !== 14).map((t) => t.lojista);
    return [
      { id: 'H1', secao: 'ecs', status: multi.length && !nomeEmVariosEc ? 'confirma' : 'contradiz', titulo: 'O EC é a chave entre Orbe e planilha; o nome não serve',
        evidencia: `${multi.length} ECs aparecem com mais de um nome na Orbe e ${nomeEmVariosEc} nome aparece em mais de um EC.` },
      { id: 'H2', secao: 'arredondamento', status: trunca === transacoes.length ? 'confirma' : 'contradiz', titulo: 'A Orbe trunca o valor da taxa em centavos',
        evidencia: `Truncar reproduz ${n(trunca)} de ${n(transacoes.length)} linhas; arredondar reproduz ${n(arred)}.` },
      { id: 'H3', secao: 'ecs', status: 'financeiro', titulo: 'ECs sem contrato na planilha não podem ser cobrados por palpite de nome',
        evidencia: `${sem.length} ECs (${n(semLinhas)} linhas) não têm linha na planilha. ${sem.filter((e) => e.n_candidatos === 1).length} deles têm exatamente um lojista sem EC com as mesmas taxas.` },
      { id: 'H4', secao: 'tempo', status: rota.length ? 'financeiro' : 'contradiz', titulo: 'Rota Global passou a pagar mais no crédito sem contrato novo',
        evidencia: `${n(rota.length)} linhas divergentes desde ${rotaDesde.split('-').reverse().join('/')}, somando ${brl(soma(rota))} a mais.` },
      { id: 'H5', secao: 'tempo', status: bridge.length ? 'confirma' : 'contradiz', titulo: 'A Bridge precisa da vigência por data (2,59% até 14/09, 2,19% depois)',
        evidencia: `${n(bridge.length)} linhas da Bridge fora da taxa vigente na data, somando ${brl(soma(bridge))}.` },
      { id: 'H6', secao: 'estornos', status: 'financeiro', titulo: 'Estorno devolve a taxa da venda original',
        evidencia: `${est.filter((v) => v.origem_no_arquivo).length} de ${est.length} estornos acham a venda no arquivo; ${estMesma} com a mesma taxa. ${est.filter((v) => !v.origem_no_arquivo).length} citam vendas de agosto. ${estVig} mudam de taxa contratada se a vigência usar a data da venda.` },
      { id: 'H7', secao: 'estornos', status: antTaxas.length === 1 && rev.every((v) => v.origem_no_arquivo) ? 'confirma' : 'contradiz', titulo: 'Antecipação é sempre 2,10% e toda reversão aponta para uma antecipação do mês',
        evidencia: `${ant.length} linhas de antecipação e reversão, taxas: ${antTaxas.join(', ')}%. ${rev.filter((v) => v.origem_no_arquivo).length} de ${rev.length} reversões acham a antecipação.` },
      { id: 'H8', secao: 'matriz', status: outras.length ? 'contradiz' : 'confirma', titulo: 'Fora Rota Global e Bridge, a Orbe aplica o contrato',
        evidencia: `${n(outras.length)} linhas divergentes em outros ECs com contrato.` },
      { id: 'H9', secao: 'ecs', status: cnpj13.length ? 'confirma' : 'contradiz', titulo: 'A planilha perde o zero à esquerda de CNPJs',
        evidencia: cnpj13.length ? `${cnpj13.join(' e ')} com ${cnpj13.length > 1 ? 'CNPJs' : 'CNPJ'} de 13 dígitos.` : 'Todos os CNPJs têm 14 dígitos.' },
    ];
  },
});

