      const contratada = vMov && vMov[faixa] !== '' ? Number(vMov[faixa]) : null;
      const contratadaVenda = vVenda && vVenda[faixa] !== '' ? Number(vVenda[faixa]) : null;
      const status = !contratos.length ? 'sem_contrato' : contratada === null ? 'sem_taxa' : Math.abs(contratada - aplicada) < 1e-9 ? 'ok' : 'divergente';
      const esperadaCent = contratada === null ? null : taxaCent(bruto, contratada);
      return {
        id_transacao: r.id_transacao, linha_arquivo: r.linha_arquivo, data: r.data_movimento, ec: r.ec,
