    const soma = (a) => Math.round(a.reduce((s, r) => s + r.diferenca_brl, 0) * 100) / 100;
    const multi = ecs.filter((e) => e.n_nomes > 1);
    const nomeEmVariosEc = (() => { const m = {}; for (const r of transacoes) (m[r.nome_orbe] = m[r.nome_orbe] || new Set()).add(r.ec); return Object.values(m).filter((s) => s.size > 1).length; })();
    const trunca = transacoes.filter((r) => r.trunca_ok).length;
